/*
 * A186783  Diameter of the symmetric group S_n when generated by the
 *          transposition (1,2) and both left and right rotations by
 *          (1,2,...,n).
 * https://oeis.org/A186783
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, more, hard
 * Formula:   a(1)=0, a(2)=1, a(3)=2, a(n)=n*(n-1)/2 for all n>=4
 * Range:     u8 n <= 13, u16 n <= 13, u32 n <= 13, u64 n <= 13, u128 n <= 13,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n == 1)
        return (seq_t)0;
    if (n == 2)
        return (seq_t)1;
    if (n == 3)
        return (seq_t)2;
    /* n >= 4 */
    return ((seq_t)n * ((seq_t)n - (seq_t)1)) / (seq_t)2;
}
